// Album records are independent of the layout. Add supplied event/BTS photos here.
// Only verified Sundance photographs are included; no stand-in BTS imagery.
const names=['Alyssa Marvin','Patrick Wilson','Margaret Cho','Sophia Torres','Molly Ringwald','Julie Christeas'];
const albums=[{id:'sundance',title:'Sundance 2026',photos:[]},{id:'bts',title:'Behind the scenes',photos:[]}];
const wall=document.querySelector('#gallery'),dialog=document.querySelector('dialog'),status=document.querySelector('#status');
let active=albums[0],current=0,request=0,opener=null;
function selectAlbum(id){active=albums.find(album=>album.id===id)||albums[0];document.querySelectorAll('[data-album]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.album===active.id)));wall.replaceChildren();status.hidden=active.photos.length>0;status.textContent='No photos in this album yet.';wall.setAttribute('aria-label',active.title+' photographs');active.photos.forEach((photo,index)=>{const button=document.createElement('button');button.className='photo';button.setAttribute('aria-label','Open '+photo.name+' photograph');const image=document.createElement('img');image.src=photo.src;image.alt=photo.name+' at Sundance 2026';image.decoding='async';image.loading=index<2?'eager':'lazy';button.append(image);button.addEventListener('click',()=>{opener=button;dialog.showModal();showPhoto(index);});wall.append(button);});wall.classList.remove('is-entering');requestAnimationFrame(()=>wall.classList.add('is-entering'));}
async function showPhoto(index){const token=++request;current=Math.max(0,Math.min(active.photos.length-1,index));const photo=active.photos[current];document.querySelector('#previous').disabled=current===0;document.querySelector('#next').disabled=current===active.photos.length-1;document.querySelector('#album-name').textContent=active.title;document.querySelector('#count').textContent=`${current+1} / ${active.photos.length}`;document.querySelector('#photo-name').textContent=photo.name;const credit=document.querySelector('#photo-credit');credit.textContent=photo.credit;credit.href=photo.page;const stage=document.querySelector('.viewer-stage');stage.setAttribute('aria-busy','true');document.querySelector('#load-error').hidden=true;try{const image=new Image();image.src=photo.src;image.alt=photo.name+' at Sundance 2026';await image.decode();if(token!==request)return;image.id='full-photo';image.className='image-enter';document.querySelector('#full-photo').replaceWith(image);}catch{if(token===request){document.querySelector('#full-photo').removeAttribute('src');document.querySelector('#full-photo').alt='';document.querySelector('#load-error').textContent='Photo could not load. Choose another photograph.';document.querySelector('#load-error').hidden=false;}}finally{if(token===request)stage.removeAttribute('aria-busy');}}
document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{request++;document.querySelector('#full-photo').removeAttribute('src');document.querySelector('#full-photo').alt='';opener?.focus();});document.querySelector('#previous').addEventListener('click',()=>showPhoto(current-1));document.querySelector('#next').addEventListener('click',()=>showPhoto(current+1));dialog.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();showPhoto(current+(event.key==='ArrowRight'?1:-1));}});
let touch=null;const stage=document.querySelector('.viewer-stage');stage.addEventListener('touchstart',event=>{touch={x:event.touches[0].clientX,y:event.touches[0].clientY};},{passive:true});stage.addEventListener('touchend',event=>{if(!touch)return;const dx=event.changedTouches[0].clientX-touch.x,dy=event.changedTouches[0].clientY-touch.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)showPhoto(current+(dx<0?1:-1));touch=null;},{passive:true});stage.addEventListener('touchcancel',()=>touch=null,{passive:true});
async function init(){const response=await fetch('../assets/portraits/sources.json');if(!response.ok)throw Error('photos');const sources=await response.json();albums[0].photos=names.map(name=>{const slug=name.toLowerCase().replaceAll(' ','-');return {name,src:`../assets/portraits/${slug}-web.jpg`,...sources.find(source=>source.slug===slug)};});albums.forEach(album=>{const button=document.createElement('button');button.dataset.album=album.id;button.textContent=album.title;button.addEventListener('click',()=>{history.pushState(null,'','#'+album.id);selectAlbum(album.id);window.scrollTo({top:0,behavior:'instant'});});document.querySelector('#albums').append(button);});selectAlbum(location.hash.slice(1));window.addEventListener('popstate',()=>{if(dialog.open)dialog.close();selectAlbum(location.hash.slice(1));});}
init().catch(()=>{status.hidden=false;status.textContent='Photos could not load. Refresh to try again.';});
